const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  const wanted = $('Config').first().json['Channel Name'];
  throw new Error(`No channel found named "${wanted}". Check spelling/casing against the channels table.`);
}
const channel = items[0].json;
return [{ json: { channel_id: channel.id, name: channel.name, niche: channel.niche, composite_score_weights: channel.composite_score_weights } }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('No videos exist yet for this channel — nothing to analyze.');
}
const ids = items.map(i => i.json.id);
return [{ json: { video_ids_filter: `in.(${ids.join(',')})` } }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('No real analytics data exists for this channel yet. analytics_snapshots is empty for its videos — nothing has completed a real YouTube publish + analytics ingestion cycle (no YouTube OAuth is wired in this build, see phase8-publishing.json sticky note). This phase will not fabricate numbers to proceed — populate real analytics_snapshots rows first.');
}
return items;

const snapshots = $('Check Analytics Exist').all().map(i => i.json);
const strategyLog = $('Get Recent Strategy Log').all().map(i => i.json);
const channel = $('Pick Channel Row').first().json;

const system = `You are the Analytics agent. Interpret this channel's recent performance and turn
it into specific next actions, not generic advice.

Channel: ${channel.name} (niche: ${channel.niche})

Data: ${JSON.stringify(snapshots, null, 2)}

Recent strategy log: ${JSON.stringify(strategyLog, null, 2)}

For each video reviewed:
- CTR, retention curve shape (where specifically people dropped off, not just the
  average), subscriber conversion
- What likely worked — tie it to a specific, concrete element (the hook, the topic
  choice, the thumbnail concept), never "the algorithm liked it"
- What likely failed, same standard of specificity

Then produce:
- 3 specific next actions for the next batch (e.g. "shorten intros to under 20
  seconds"; "the geopolitics-explainer angle is outperforming company-history 2:1 —
  weight topic discovery toward it")
- An updated composite scoring note if the data suggests the demand/competition/
  novelty/evergreen weights should shift for this channel specifically

Never recommend an action justified only by "this would increase views" without also
weighing retention and channel trust — a channel that chases CTR alone degrades its
own recommendations over time.

--- RESPONSE FORMAT ---

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "video_reviews": [
    {
      "video_id_or_short_id": string,
      "ctr_interpretation": string,
      "retention_interpretation": string,
      "subscriber_conversion_interpretation": string,
      "what_worked": string,
      "what_failed": string
    }
  ],
  "next_actions": [string, string, string],
  "updated_composite_score_weights": { "demand": number, "competition": number, "novelty": number, "evergreen": number } | null
}`;

return [{ json: { system } }];

const raw = $input.first().json["Claude's Analytics JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
const valid = parsed && Array.isArray(parsed.video_reviews) && Array.isArray(parsed.next_actions) && parsed.next_actions.length === 3;
if (parseError || !valid) {
  throw new Error('Could not parse a valid Analytics JSON (needs video_reviews array and next_actions: exactly 3 items). Paste error: ' + (parseError || 'missing/malformed fields'));
}

const channel = $('Pick Channel Row').first().json;
const today = new Date();
const day = today.getUTCDay();
const diffToMonday = (day === 0 ? -6 : 1) - day;
const monday = new Date(today);
monday.setUTCDate(today.getUTCDate() + diffToMonday);
const weekOf = monday.toISOString().slice(0, 10);

const hasWeightUpdate = !!(parsed.updated_composite_score_weights && typeof parsed.updated_composite_score_weights === 'object');

return [{ json: {
  channel_id: channel.channel_id,
  channel_name: channel.name,
  week_of: weekOf,
  insights: { video_reviews: parsed.video_reviews },
  next_actions: parsed.next_actions,
  has_weight_update: hasWeightUpdate,
  updated_weights: hasWeightUpdate ? parsed.updated_composite_score_weights : null
} }];

const parsed = $('Parse Analytics JSON').first().json;
return [{ json: {
  result: `Strategy log entry saved for week of ${parsed.week_of}.`,
  channel: parsed.channel_name,
  next_actions: parsed.next_actions,
  composite_weights_updated: parsed.has_weight_update
} }];
